#### [§](https://docs.rs/git2/latest/git2/#initializing-a-new-repository) Initializing a new repository
```
use git2::Repository;

let repo = match Repository::init("/path/to/a/repo") {
    Ok(repo) => repo,
    Err(e) => panic!("failed to init: {}", e),
};
```

#### [§](https://docs.rs/git2/latest/git2/#opening-an-existing-repository) Opening an existing repository
```
use git2::Repository;

let repo = match Repository::open("/path/to/a/repo") {
    Ok(repo) => repo,
    Err(e) => panic!("failed to open: {}", e),
};
```

#### [§](https://docs.rs/git2/latest/git2/#cloning-an-existing-repository) Cloning an existing repository
```
use git2::Repository;

let url = "https://github.com/alexcrichton/git2-rs";
let repo = match Repository::clone(url, "/path/to/a/repo") {
    Ok(repo) => repo,
    Err(e) => panic!("failed to clone: {}", e),
};
